SELECT FROM BLACKLIST_ALERT
AND ALERT_STATUS = #{status}
ORDER BY CREATED_TIME DESC

SELECT *
FROM (
    SELECT t.*, ROW_NUMBER() OVER (ORDER BY t.CREATED_TIME DESC) AS RN
    FROM BLACKLIST_ALERT t


            AND t.BATCH_ID = #{batchId}


            AND t.ALERT_LEVEL = #{alertLevel}


            AND t.ALERT_STATUS = #{status}


            AND t.SUPPLIER_NAME LIKE '%' || #{supplierName} || '%'


) t
WHERE t.RN > #{startRow} AND t.RN <= #{endRow}

SELECT COUNT(1)
FROM BLACKLIST_ALERT


        AND BATCH_ID = #{batchId}


        AND ALERT_LEVEL = #{alertLevel}


        AND ALERT_STATUS = #{status}


        AND SUPPLIER_NAME LIKE '%' || #{supplierName} || '%'

SELECT COUNT(1)
FROM BLACKLIST_ALERT
WHERE BATCH_ID = #{batchId}
  AND SUPPLIER_NAME = #{supplierName}

